/* Material Intensity Presets */
.halo-intensity-subtle {
  --halo-active-blur: var(--halo-blur-sm);
  --halo-active-highlight: 0.4;
  --halo-active-edge: 0.7;
}

.halo-intensity-balanced {
  --halo-active-blur: var(--halo-blur-md);
  --halo-active-highlight: 0.85;
  --halo-active-edge: 1;
}

.halo-intensity-rich {
  --halo-active-blur: var(--halo-blur-lg);
  --halo-active-highlight: 1.2;
  --halo-active-edge: 1.35;
}

/* Tactile Physics Classes */
.halo-tactile-press {
  transition: transform 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              box-shadow 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              background-color 150ms ease;
}

.halo-tactile-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
  box-shadow: var(--halo-shadow-compressed), var(--halo-edge-inner), var(--halo-edge-outer) !important;
}

/* Focus Ring Accessibility Infrastructure */
.halo-focus-ring {
  outline: none;
}

.halo-focus-ring:focus-visible {
  outline: 2px solid var(--halo-focus-color) !important;
  outline-offset: var(--halo-focus-offset) !important;
  box-shadow: var(--halo-focus-shadow) !important;
  z-index: 10;
}

/* Forced Colors (High Contrast Mode) */
@media (forced-colors: active) {
  .halo-focus-ring:focus-visible {
    outline: 2px solid Highlight !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
  }
}

/* Motion Presets Classes */
.halo-motion-press {
  transition: transform var(--halo-duration-micro) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-micro) var(--halo-ease-tactile);
}

.halo-motion-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
}

.halo-motion-lift {
  transition: transform var(--halo-duration-state) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-state) var(--halo-ease-tactile);
}

.halo-motion-lift:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--halo-shadow-elevated);
}

.halo-motion-reveal {
  animation: halo-reveal var(--halo-duration-reveal) var(--halo-ease-spring) forwards;
}

.halo-motion-settle {
  transition: transform var(--halo-duration-settle) var(--halo-ease-spring),
              opacity var(--halo-duration-reveal) ease;
}

.halo-motion-float {
  animation: halo-float 3.5s ease-in-out infinite alternate;
}

@keyframes halo-reveal {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes halo-float {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-6px);
  }
}

/* Reduced Motion Override */
@media (prefers-reduced-motion: reduce) {
  .halo-tactile-press,
  .halo-motion-press,
  .halo-motion-lift,
  .halo-motion-reveal,
  .halo-motion-settle,
  .halo-motion-float,
  .halo-motion-transition {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transform: none !important;
  }
}

/* ==========================================================================
   HALOUI MATERIAL INTENSITY ORCHESTRATION
   ========================================================================== */
[data-material-intensity="subtle"],
.halo-intensity-subtle {
  --halo-blur-strength: 8px;
  --halo-highlight-multiplier: 0.40;
  --halo-glow-spread: 12px;
}

[data-material-intensity="balanced"],
.halo-intensity-balanced {
  --halo-blur-strength: 16px;
  --halo-highlight-multiplier: 0.85;
  --halo-glow-spread: 24px;
}

[data-material-intensity="rich"],
.halo-intensity-rich {
  --halo-blur-strength: 28px;
  --halo-highlight-multiplier: 1.20;
  --halo-glow-spread: 36px;
}

/* ==========================================================================
   HALOUI PHYSICAL LIQUID GLASS BUTTON ENGINE
   ========================================================================== */
.halo-liquid-glass {
  position: relative;
  isolation: isolate;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(8px) saturate(180%);
  -webkit-backdrop-filter: blur(8px) saturate(180%);
  border: 1px double rgba(51, 51, 51, 0.12);
  box-shadow:
    inset 2px -2px 1px -1px rgba(255, 255, 255, 0.95),
    inset -2px 2px 1px -1px rgba(255, 255, 255, 0.95),
    inset 6px -6px 1px -6px rgba(255, 255, 255, 0.65),
    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.65),
    inset 0 0 2px rgba(0, 0, 0, 0.35),
    0 4px 14px rgba(0, 0, 0, 0.12);
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1),
              box-shadow 0.2s cubic-bezier(0.2, 0.8, 0.2, 1),
              background 0.2s ease;
}

.dark .halo-liquid-glass,
[data-stage-theme="dark"] .halo-liquid-glass {
  background: rgba(255, 255, 255, 0.03);
  border: 1px double rgba(255, 255, 255, 0.16);
  box-shadow:
    inset 2px -2px 1px -1px rgba(255, 255, 255, 0.5),
    inset -2px 2px 1px -1px rgba(255, 255, 255, 0.5),
    inset 6px -6px 1px -6px rgba(255, 255, 255, 0.3),
    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.3),
    inset 0 0 2px rgba(0, 0, 0, 0.8),
    0 6px 20px -2px rgba(0, 0, 0, 0.6);
}

.halo-liquid-glass::before {
  content: "";
  position: absolute;
  z-index: 1;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.75) 0%,
    transparent 25%,
    transparent 75%,
    rgba(255, 255, 255, 0.75) 100%
  );
  filter: blur(1px);
  opacity: 0.9;
  transition: opacity 0.2s ease;
}

.dark .halo-liquid-glass::before,
[data-stage-theme="dark"] .halo-liquid-glass::before {
  background: linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.4) 0%,
    transparent 25%,
    transparent 75%,
    rgba(255, 255, 255, 0.4) 100%
  );
}

.halo-liquid-glass::after {
  content: "";
  position: absolute;
  z-index: 0;
  inset: 2px;
  border-radius: inherit;
  border: 1px solid rgba(0, 0, 0, 0.15);
  filter: blur(3px);
  pointer-events: none;
}

.dark .halo-liquid-glass::after,
[data-stage-theme="dark"] .halo-liquid-glass::after {
  border: 1px solid rgba(255, 255, 255, 0.12);
  filter: blur(3px);
}

.halo-liquid-glass:hover {
  transform: translateY(-2px);
  background: rgba(255, 255, 255, 0.1);
  box-shadow:
    inset 2px -2px 1px -1px rgba(255, 255, 255, 1),
    inset -2px 2px 1px -1px rgba(255, 255, 255, 1),
    inset 6px -6px 1px -6px rgba(255, 255, 255, 0.8),
    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.8),
    inset 0 0 2px rgba(0, 0, 0, 0.25),
    0 8px 24px -2px rgba(0, 0, 0, 0.18);
}

.dark .halo-liquid-glass:hover,
[data-stage-theme="dark"] .halo-liquid-glass:hover {
  background: rgba(255, 255, 255, 0.07);
  box-shadow:
    inset 2px -2px 1px -1px rgba(255, 255, 255, 0.7),
    inset -2px 2px 1px -1px rgba(255, 255, 255, 0.7),
    inset 6px -6px 1px -6px rgba(255, 255, 255, 0.4),
    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.4),
    inset 0 0 2px rgba(0, 0, 0, 0.6),
    0 10px 28px -2px rgba(0, 0, 0, 0.7);
}

.halo-liquid-glass:active {
  transform: scale(0.95);
}
